133	            @Pattern(regexp = DATE) String termsFrom,
134	            @Pattern(regexp = DATE) String termsAFrom,
135	            @Pattern(regexp = DATE) String termsBFrom,
136	            @Pattern(regexp = DATE) String termsCFrom,
137	            @Pattern(regexp = DATE) String latePctFrom,
