147	    /** A from-date as typed: blank, or yyyy-mm-dd. */
148	    private static final String DATE = "|\\d{4}-\\d{2}-\\d{2}";
149	
150	    /** A value a dated setting has from a from-date (null for the beginning of time); the value as the setting
151	     * shows it, null for none. */
152	    public record DatedView(String from, String value) {}
