179	            }
180	            return new SettingsView(clerkLimit != null ? clerkLimit.setScale(2).toPlainString() : null,
181	                    sheet.getFloor().toPlainString(), sheet.getTerms(), sheet.getGradeTerms("A"),
182	                    sheet.getGradeTerms("B"), sheet.getGradeTerms("C"), sheet.getLatePct().toPlainString(),
