430	                froms.get(Sheet.gradeTermsKey(grade))));
431	        if (latePct != null) {
432	            setLatePct(user, sheetId, latePct, froms.get(Sheet.LATE_PCT));
433	        }
434	        if (policyDate != null) {
435	            setPolicyDate(user, sheetId, policyDate.orElse(null));
436	        }
437	        if (periodNumberingFrom != null) {
438	            setPeriodNumberingFrom(user, sheetId, periodNumberingFrom.orElse(null));
439	        }
440	        if (cap != null) {
441	            setCap(user, sheetId, cap.orElse(null), froms.get(Sheet.CAP));
442	        }
443	        if (proofThreshold != null) {
444	            setProofThreshold(user, sheetId, proofThreshold.orElse(null), froms.get(Sheet.PROOF_THRESHOLD));
445	        }
446	        if (graceDays != null) {
447	            setGraceDays(user, sheetId, graceDays.orElse(null));
448	        }
449	        permissions.forEach((action, given) -> setPermission(user, sheetId, action, given));
