750	/** Refuse every change a viewer asks of a sheet: any request on a sheet other than a read, before it reaches its
751	 * handler, so it writes nothing and records nothing. Loading the sheet is a read. Opening or settling claims
752	 * together goes through, so that each claim is refused on its own and counted as refused. */
753	@Configuration
754	public class ViewerGuard implements HandlerInterceptor, WebMvcConfigurer {
755	
756	    private final SettingService settings;
757	
758	    public ViewerGuard(SettingService settings) {
759	        this.settings = settings;
760	    }
761	
762	    @Override
763	    public void addInterceptors(InterceptorRegistry registry) {
764	        registry.addInterceptor(this).addPathPatterns("/api/sheets/{sheet}/**").excludePathPatterns("/api/sheets/load",
765	                "/api/sheets/{sheet}/claims/open", "/api/sheets/{sheet}/claims/settle");
766	    }
767	
768	    @Override
769	    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
770	        if (HttpMethod.GET.matches(request.getMethod()) || HttpMethod.HEAD.matches(request.getMethod())
771	                || HttpMethod.OPTIONS.matches(request.getMethod())) {
772	            return true;
773	        }
774	        String user = request.getHeader("X-User");
775	        @SuppressWarnings("unchecked")
776	        Map<String, String> vars = (Map<String, String>) request
777	                .getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
778	        String sheetId = vars == null ? null : vars.getOrDefault("sheetId", vars.get("id"));
779	        if (user != null && sheetId != null && settings.roleOf(sheetId, user.trim()) == Role.VIEWER) {
780	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "A viewer cannot change anything.");
781	        }
782	        return true;
783	    }
784	}
