787	import java.io.IOException;
788	import java.io.UncheckedIOException;
789	import java.nio.charset.StandardCharsets;
790	import java.nio.file.Files;
791	import java.nio.file.Path;
792	import java.nio.file.StandardOpenOption;
793	import org.springframework.beans.factory.annotation.Value;
794	import org.springframework.stereotype.Service;
795	import org.springframework.transaction.support.TransactionSynchronization;
796	import org.springframework.transaction.support.TransactionSynchronizationManager;
797	
798	/**
799	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
800	 * so tests can assert side-effects by reading that file — the second test-assertion channel
801	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
802	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
803	 *
804	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
805	 * SYNC) so a test reads the record immediately.
806	 */
807	@Service
808	public class Audit {
809	
810	    private final Path file;
811	
812	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
813	        this.file = Path.of(path);
814	    }
815	
816	    /** Append one audit record. Tests assert the exact line(s) in the file. */
817	    public synchronized void record(String entry) {
818	        try {
819	            Path parent = file.toAbsolutePath().getParent();
820	            if (parent != null) {
821	                Files.createDirectories(parent);
822	            }
823	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
824	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
825	        } catch (IOException e) {
826	            throw new UncheckedIOException(e);
827	        }
828	    }
829	
830	    /**
831	     * Append one audit record once the current transaction commits, so a change that is refused or
832	     * rolled back writes nothing. Outside a transaction the record is appended at once.
833	     */
834	    public void recordOnCommit(String entry) {
835	        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
836	            record(entry);
837	            return;
838	        }
839	        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
840	            @Override
841	            public void afterCommit() {
842	                record(entry);
843	            }
844	        });
845	    }
846	
847	    /** Truncate the audit file. */
848	    public synchronized void clear() {
849	        try {
850	            Files.deleteIfExists(file);
851	        } catch (IOException e) {
852	            throw new UncheckedIOException(e);
853	        }
854	    }
855	}
