package net.officefloor.hq.app.setting;

import java.util.Arrays;
import java.util.List;
import java.util.Optional;

/** An action the sheet's permission matrix governs, with the roles that may take it under the standing rule (when
 * the sheet gives none of its own). */
public enum Permission {
    OPEN("open a claim", Role.CLERK, Role.STEWARD),
    SETTLE("settle a claim", Role.CLERK, Role.STEWARD),
    VOID("void a claim", Role.CLERK, Role.STEWARD),
    REASSIGN("move a claim", Role.STEWARD),
    CLOSE("close a period", Role.CLERK, Role.STEWARD),
    REOPEN("reopen a period", Role.STEWARD);

    private final String doing;
    private final List<Role> standing;

    Permission(String doing, Role... standing) {
        this.doing = doing;
        this.standing = List.of(standing);
    }

    /** The action as it is named, e.g. "open". */
    public String code() {
        return name().toLowerCase();
    }

    /** The key the setting is kept and audited by, e.g. "perm-open". */
    public String key() {
        return "perm-" + code();
    }

    /** What the action does, e.g. "open a claim". */
    public String doing() {
        return doing;
    }

    /** The roles that may take the action when the sheet gives none of its own. */
    public List<Role> standing() {
        return standing;
    }

    public static Optional<Permission> of(String code) {
        return Arrays.stream(values()).filter(p -> p.code().equals(code)).findFirst();
    }
}
package net.officefloor.hq.app.setting;

import java.util.Arrays;
import java.util.Optional;

/** The role a user name has on a sheet; any name without one is a clerk. A viewer sees the sheet and changes
 * nothing. */
public enum Role {
    CLERK, STEWARD, VIEWER;

    /** The role as it is typed and shown, e.g. "steward". */
    public String code() {
        return name().toLowerCase();
    }

    public static Optional<Role> of(String code) {
        return Arrays.stream(values()).filter(r -> r.code().equals(code)).findFirst();
    }
}
package net.officefloor.hq.app.setting;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import net.officefloor.hq.app.sheet.Sheet;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

/** A sheet's settings: the role each user name has, its clerk limit, its floor, its terms, its late percent, its policy date, its period numbering date, its cap and its proof threshold. */
@RestController
@RequestMapping("/api/sheets/{sheetId}")
public class SettingController {

    /** The role is clerk, steward or viewer. */
    public record RoleForm(@NotBlank @Size(max = 100) String user, @NotNull String role) {}

    public record RoleView(String user, String role) {

        static RoleView of(SheetRole role) {
            return new RoleView(role.getUser(), role.getRole().code());
        }
    }

    /** The clerk limit has up to two decimals, 0.00 or more; blank means no limit. The floor has up to two
     * decimals, 0.00 or more. The terms are a whole number of days, 0 or more; so are each grade's terms, where
     * blank means the grade uses the sheet's terms. The late percent has up to two
     * decimals, 0.00 or more. The policy date is a date (yyyy-mm-dd); blank means the sheet's today. The period numbering date is a date; blank means
     * off. The cap has up to two decimals, 0.00 or more; blank means no cap. The proof threshold has up to two
     * decimals, 0.00 or more; blank means none. The grace days are a whole number of days, 0 or more; blank means
     * off. A setting
     * left out (null) is left as it is. Each setting that carries a figure has a from-date (yyyy-mm-dd) its value
     * is recorded from; blank or left out means the sheet's today. Each permission (open, settle, void, reassign,
     * close, reopen) is the roles that may take the action, comma separated; blank keeps the standing rule. */
    public record SettingsForm(@Pattern(regexp = "|\\d{1,10}(\\.\\d{1,2})?") String clerkLimit,
            @Pattern(regexp = "\\d{1,10}(\\.\\d{1,2})?") String floor,
            @Pattern(regexp = "\\d{1,5}") String terms,
            @Pattern(regexp = "|\\d{1,5}") String termsA,
            @Pattern(regexp = "|\\d{1,5}") String termsB,
            @Pattern(regexp = "|\\d{1,5}") String termsC,
            @Pattern(regexp = "\\d{1,5}(\\.\\d{1,2})?") String latePct,
            @Pattern(regexp = "|\\d{4}-\\d{2}-\\d{2}") String policyDate,
            @Pattern(regexp = "|\\d{4}-\\d{2}-\\d{2}") String periodNumberingFrom,
            @Pattern(regexp = "|\\d{1,10}(\\.\\d{1,2})?") String cap,
            @Pattern(regexp = "|\\d{1,10}(\\.\\d{1,2})?") String proofThreshold,
            @Pattern(regexp = "|\\d{1,5}") String graceDays,
            @Pattern(regexp = DATE) String clerkLimitFrom,
            @Pattern(regexp = DATE) String floorFrom,
            @Pattern(regexp = DATE) String termsFrom,
            @Pattern(regexp = DATE) String termsAFrom,
            @Pattern(regexp = DATE) String termsBFrom,
            @Pattern(regexp = DATE) String termsCFrom,
            @Pattern(regexp = DATE) String latePctFrom,
            @Pattern(regexp = DATE) String capFrom,
            @Pattern(regexp = DATE) String proofThresholdFrom,
            @Size(max = 100) String permOpen,
            @Size(max = 100) String permSettle,
            @Size(max = 100) String permVoid,
            @Size(max = 100) String permReassign,
            @Size(max = 100) String permClose,
            @Size(max = 100) String permReopen) {}

    /** A from-date as typed: blank, or yyyy-mm-dd. */
    private static final String DATE = "|\\d{4}-\\d{2}-\\d{2}";

    /** A value a dated setting has from a from-date (null for the beginning of time); the value as the setting
     * shows it, null for none. */
    public record DatedView(String from, String value) {}

    /** The clerk limit and floor are shown with two decimals; the clerk limit is null when there is none. The
     * terms are the days after its date a claim is due by; each grade's terms are null when it uses the sheet's. The late percent is shown with two decimals. The policy date is null when there is none (the sheet's
     * today is used). The period numbering date is null when it is off. The cap is shown with two decimals,
     * null when there is none; so is the proof threshold. The grace days are null when they are off. Each of these that carries a figure is the value in force on the sheet's today;
     * {@code dated} has, by key, every value recorded for it by from-date. {@code permissions} has, by action, the
     * roles that may take it, comma separated, blank for the standing rule. */
    public record SettingsView(String clerkLimit, String floor, int terms, Integer termsA, Integer termsB,
            Integer termsC, String latePct, String policyDate, String periodNumberingFrom, String cap,
            String proofThreshold, Integer graceDays, Map<String, List<DatedView>> dated, Map<String, String> permissions) {

        static SettingsView of(Sheet sheet) {
            BigDecimal clerkLimit = sheet.getClerkLimit();
            BigDecimal cap = sheet.getCap();
            BigDecimal proofThreshold = sheet.getProofThreshold();
            Map<String, List<DatedView>> dated = new LinkedHashMap<>();
            for (String key : List.of(Sheet.CLERK_LIMIT, Sheet.FLOOR, Sheet.TERMS, Sheet.LATE_PCT, Sheet.CAP,
                    Sheet.PROOF_THRESHOLD)) {
                dated.put(key, history(sheet, key, !key.equals(Sheet.TERMS)));
            }
            for (String grade : GRADES) {
                dated.put(Sheet.gradeTermsKey(grade), history(sheet, Sheet.gradeTermsKey(grade), false));
            }
            Map<String, String> permissions = new LinkedHashMap<>();
            for (Permission action : Permission.values()) {
                permissions.put(action.code(), SettingService.permissionOf(sheet, action));
            }
            return new SettingsView(clerkLimit != null ? clerkLimit.setScale(2).toPlainString() : null,
                    sheet.getFloor().toPlainString(), sheet.getTerms(), sheet.getGradeTerms("A"),
                    sheet.getGradeTerms("B"), sheet.getGradeTerms("C"), sheet.getLatePct().toPlainString(),
                    sheet.getPolicyDate() != null ? sheet.getPolicyDate().toString() : null,
                    sheet.getPeriodNumberingFrom() != null ? sheet.getPeriodNumberingFrom().toString() : null,
                    cap != null ? cap.setScale(2).toPlainString() : null,
                    proofThreshold != null ? proofThreshold.setScale(2).toPlainString() : null,
                    sheet.getGraceDays(), dated,
                    permissions);
        }

        /** The values recorded for a key by from-date, shown with two decimals when {@code amount}, else as whole
         * days. */
        private static List<DatedView> history(Sheet sheet, String key, boolean amount) {
            return sheet.history(key).stream()
                    .map(d -> new DatedView(d.getFrom() != null ? d.getFrom().toString() : null,
                            d.getValue() == null ? null
                                    : amount ? d.getValue().setScale(2).toPlainString()
                                            : String.valueOf(d.getValue().intValue())))
                    .toList();
        }
    }

    /** The grades that can have terms of their own. */
    private static final List<String> GRADES = List.of("A", "B", "C");

    private final SettingService service;

    public SettingController(SettingService service) {
        this.service = service;
    }

    @GetMapping("/roles")
    public List<RoleView> roles(@RequestHeader("X-User") String user, @PathVariable String sheetId) {
        return service.roles(sheetId).stream().map(RoleView::of).toList();
    }

    @PutMapping("/roles")
    public RoleView setRole(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @Valid @RequestBody RoleForm form) {
        Role role = Role.of(form.role().trim()).orElseThrow(
                () -> new ResponseStatusException(HttpStatus.BAD_REQUEST, "A role is clerk, steward or viewer."));
        return RoleView.of(service.setRole(user, sheetId, form.user().trim(), role));
    }

    @GetMapping("/settings")
    public SettingsView settings(@RequestHeader("X-User") String user, @PathVariable String sheetId) {
        return view(sheetId);
    }

    @PutMapping("/settings")
    public SettingsView save(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @Valid @RequestBody SettingsForm form) {
        String limit = form.clerkLimit();
        Optional<BigDecimal> clerkLimit = amountOrBlank(limit);
        Optional<BigDecimal> cap = amountOrBlank(form.cap());
        Optional<BigDecimal> proofThreshold = amountOrBlank(form.proofThreshold());
        Optional<LocalDate> policyDate = dateOrBlank(form.policyDate(), "A policy date is a date, or blank.");
        Optional<LocalDate> periodNumberingFrom = dateOrBlank(form.periodNumberingFrom(),
                "A period numbering date is a date, or blank.");
        service.save(user, sheetId, clerkLimit, form.floor() == null ? null : new BigDecimal(form.floor()),
                form.terms() == null ? null : Integer.valueOf(form.terms()), gradeTerms(form),
                form.latePct() == null ? null : new BigDecimal(form.latePct()), policyDate, periodNumberingFrom, cap,
                proofThreshold, form.graceDays() == null ? null
                        : form.graceDays().isEmpty() ? Optional.empty() : Optional.of(Integer.valueOf(form.graceDays())),
                froms(form), permissions(form));
        return view(sheetId);
    }

    private SettingsView view(String sheetId) {
        return SettingsView.of(service.sheet(sheetId));
    }

    /** The from-dates given, by the key of their setting; a setting without one is recorded from the sheet's
     * today. */
    private static Map<String, LocalDate> froms(SettingsForm form) {
        Map<String, String> typed = new LinkedHashMap<>();
        typed.put(Sheet.CLERK_LIMIT, form.clerkLimitFrom());
        typed.put(Sheet.FLOOR, form.floorFrom());
        typed.put(Sheet.TERMS, form.termsFrom());
        typed.put(Sheet.gradeTermsKey("A"), form.termsAFrom());
        typed.put(Sheet.gradeTermsKey("B"), form.termsBFrom());
        typed.put(Sheet.gradeTermsKey("C"), form.termsCFrom());
        typed.put(Sheet.LATE_PCT, form.latePctFrom());
        typed.put(Sheet.CAP, form.capFrom());
        typed.put(Sheet.PROOF_THRESHOLD, form.proofThresholdFrom());
        Map<String, LocalDate> froms = new LinkedHashMap<>();
        typed.forEach((key, from) -> {
            Optional<LocalDate> date = dateOrBlank(from, "A from-date is a date, or blank.");
            if (date != null && date.isPresent()) {
                froms.put(key, date.get());
            }
        });
        return froms;
    }

    /** The permissions given, in action order, each the roles typed (blank keeps the standing rule); an action
     * left out is left as it is. */
    private static Map<Permission, List<Role>> permissions(SettingsForm form) {
        Map<Permission, String> typed = new LinkedHashMap<>();
        typed.put(Permission.OPEN, form.permOpen());
        typed.put(Permission.SETTLE, form.permSettle());
        typed.put(Permission.VOID, form.permVoid());
        typed.put(Permission.REASSIGN, form.permReassign());
        typed.put(Permission.CLOSE, form.permClose());
        typed.put(Permission.REOPEN, form.permReopen());
        Map<Permission, List<Role>> given = new LinkedHashMap<>();
        typed.forEach((action, roles) -> {
            if (roles != null) {
                given.put(action, rolesOf(roles));
            }
        });
        return given;
    }

    /** The roles typed, comma separated, each once in the order typed; none when blank. */
    private static List<Role> rolesOf(String typed) {
        if (typed.isBlank()) {
            return List.of();
        }
        List<Role> roles = new ArrayList<>();
        for (String code : typed.split(",", -1)) {
            Role role = Role.of(code.trim()).orElseThrow(() -> new ResponseStatusException(HttpStatus.BAD_REQUEST,
                    "A permission is roles (clerk or steward), comma separated, or blank."));
            if (!roles.contains(role)) {
                roles.add(role);
            }
        }
        return roles;
    }

    /** The grades' terms given, in grade order: empty when blank (the grade uses the sheet's terms); a grade
     * left out is left as it is. */
    private static Map<String, Optional<Integer>> gradeTerms(SettingsForm form) {
        Map<String, Optional<Integer>> given = new LinkedHashMap<>();
        Map<String, String> typed = new LinkedHashMap<>();
        typed.put("A", form.termsA());
        typed.put("B", form.termsB());
        typed.put("C", form.termsC());
        typed.forEach((grade, days) -> {
            if (days != null) {
                given.put(grade, days.isEmpty() ? Optional.empty() : Optional.of(Integer.valueOf(days)));
            }
        });
        return given;
    }

    /** An amount setting as given: null when left out, empty when blank. */
    private static Optional<BigDecimal> amountOrBlank(String amount) {
        return amount == null ? null : amount.isEmpty() ? Optional.empty() : Optional.of(new BigDecimal(amount));
    }

    /** A date setting as given: null when left out, empty when blank. */
    private static Optional<LocalDate> dateOrBlank(String date, String refusal) {
        try {
            return date == null ? null : date.isEmpty() ? Optional.empty() : Optional.of(LocalDate.parse(date));
        } catch (DateTimeParseException e) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, refusal);
        }
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.rollup.RollupService.Snapshot;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** A sheet's settings: the role each user name has on it, its clerk limit, its floor, its terms, its late percent, its policy date, its period numbering date and its cap; those that carry a figure are dated. */
@Service
public class SettingService {

    private final SheetRoleRepository roles;
    private final SheetRepository sheetRepository;
    private final SheetService sheets;
    private final RollupService rollup;
    private final Audit audit;

    public SettingService(SheetRoleRepository roles, SheetRepository sheetRepository, SheetService sheets,
            RollupService rollup, Audit audit) {
        this.roles = roles;
        this.sheetRepository = sheetRepository;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** The roles given on the sheet. */
    @Transactional(readOnly = true)
    public List<SheetRole> roles(String sheetId) {
        sheets.today(sheetId); // the sheet must exist
        return roles.findBySheetIdOrderById(sheetId);
    }

    /** The role a user name has on the sheet: a clerk unless given another. */
    @Transactional(readOnly = true)
    public Role roleOf(String sheetId, String user) {
        return roles.findBySheetIdAndUser(sheetId, user).map(SheetRole::getRole).orElse(Role.CLERK);
    }

    /** Give a user name a role on the sheet, replacing any it had. */
    @Transactional
    public SheetRole setRole(String user, String sheetId, String name, Role role) {
        sheets.lock(sheetId);
        SheetRole given = roles.findBySheetIdAndUser(sheetId, name).orElse(null);
        if (given == null) {
            given = roles.saveAndFlush(new SheetRole(sheetId, name, role));
        } else {
            given.setRole(role);
            roles.flush();
        }
        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user + " user=" + name + " role=" + role.code());
        return given;
    }

    /** Save the settings given, the clerk limit, the floor, the terms, each grade's terms (in the order given),
     * the late percent then the policy date, the period numbering date, the cap, the proof threshold and the
     * permission matrix (each action in the order given) together; a
     * setting not given (null) is left as it is, and an empty clerk limit, grade's terms, policy date, period
     * numbering date, cap, proof threshold or grace days removes it; the grace days are saved after the proof
     * threshold. A setting that carries a figure is recorded from its from-date in {@code froms}, by key, or
     * from the sheet's today when none is given. */
    @Transactional
    public void save(String user, String sheetId, Optional<BigDecimal> clerkLimit, BigDecimal floor,
            Integer terms, Map<String, Optional<Integer>> gradeTerms, BigDecimal latePct,
            Optional<LocalDate> policyDate, Optional<LocalDate> periodNumberingFrom, Optional<BigDecimal> cap,
            Optional<BigDecimal> proofThreshold, Optional<Integer> graceDays, Map<String, LocalDate> froms,
            Map<Permission, List<Role>> permissions) {
        if (clerkLimit != null) {
            setClerkLimit(user, sheetId, clerkLimit.orElse(null), froms.get(Sheet.CLERK_LIMIT));
        }
        if (floor != null) {
            setFloor(user, sheetId, floor, froms.get(Sheet.FLOOR));
        }
        if (terms != null) {
            setTerms(user, sheetId, terms, froms.get(Sheet.TERMS));
        }
        gradeTerms.forEach((grade, days) -> setGradeTerms(user, sheetId, grade, days.orElse(null),
                froms.get(Sheet.gradeTermsKey(grade))));
        if (latePct != null) {
            setLatePct(user, sheetId, latePct, froms.get(Sheet.LATE_PCT));
        }
        if (policyDate != null) {
            setPolicyDate(user, sheetId, policyDate.orElse(null));
        }
        if (periodNumberingFrom != null) {
            setPeriodNumberingFrom(user, sheetId, periodNumberingFrom.orElse(null));
        }
        if (cap != null) {
            setCap(user, sheetId, cap.orElse(null), froms.get(Sheet.CAP));
        }
        if (proofThreshold != null) {
            setProofThreshold(user, sheetId, proofThreshold.orElse(null), froms.get(Sheet.PROOF_THRESHOLD));
        }
        if (graceDays != null) {
            setGraceDays(user, sheetId, graceDays.orElse(null));
        }
        permissions.forEach((action, given) -> setPermission(user, sheetId, action, given));
    }

    /** The sheet, for the values its dated settings have. */
    @Transactional(readOnly = true)
    public Sheet sheet(String sheetId) {
        return find(sheetId);
    }

    /** The sheet's clerk limit in force on its today; none means no limit. */
    @Transactional(readOnly = true)
    public BigDecimal clerkLimit(String sheetId) {
        return find(sheetId).getClerkLimit();
    }

    /** Set the sheet's clerk limit from a date (the sheet's today when none); none removes it from then. */
    @Transactional
    public BigDecimal setClerkLimit(String user, String sheetId, BigDecimal limit, LocalDate from) {
        BigDecimal value = limit != null ? limit.setScale(2) : null;
        record(user, sheetId, Sheet.CLERK_LIMIT, from, value, value != null ? value.toPlainString() : "", false);
        return value;
    }

    /** Set the sheet's floor from a date (the sheet's today when none); it moves every live due below it of a
     * claim dated from then until a later one, and the figures it moves are written after. */
    @Transactional
    public BigDecimal setFloor(String user, String sheetId, BigDecimal floor, LocalDate from) {
        BigDecimal value = floor.setScale(2);
        record(user, sheetId, Sheet.FLOOR, from, value, value.toPlainString(), true);
        return value;
    }

    /** Set the sheet's terms from a date (the sheet's today when none); they go for claims added from now on
     * dated from then (a claim's due-by is fixed when it is added), so they move no figure. */
    @Transactional
    public int setTerms(String user, String sheetId, int terms, LocalDate from) {
        record(user, sheetId, Sheet.TERMS, from, BigDecimal.valueOf(terms), String.valueOf(terms), false);
        return terms;
    }

    /** Set a grade's own terms from a date (the sheet's today when none), none to have it use the sheet's from
     * then; like the sheet's terms they go for claims added from now on. */
    @Transactional
    public Integer setGradeTerms(String user, String sheetId, String grade, Integer terms, LocalDate from) {
        record(user, sheetId, Sheet.gradeTermsKey(grade), from, terms != null ? BigDecimal.valueOf(terms) : null,
                terms != null ? terms.toString() : "", false);
        return terms;
    }

    /** The terms in force for a claim of a person of the grade dated on a date: the grade's own, else the
     * sheet's. */
    @Transactional(readOnly = true)
    public int termsFor(String sheetId, String grade, LocalDate date) {
        return find(sheetId).termsFor(grade, date);
    }

    /** Set the sheet's late percent from a date (the sheet's today when none); it moves the late charge every
     * overdue claim gains on a 30-day boundary from then until a later one, and the figures it moves are written after. */
    @Transactional
    public BigDecimal setLatePct(String user, String sheetId, BigDecimal latePct, LocalDate from) {
        BigDecimal value = latePct.setScale(2);
        record(user, sheetId, Sheet.LATE_PCT, from, value, value.toPlainString(), true);
        return value;
    }

    /** The sheet's policy date: a claim dated before it rounds half up, one dated on or after it half to even;
     * none means the sheet's today. */
    @Transactional(readOnly = true)
    public LocalDate policyDate(String sheetId) {
        return find(sheetId).getPolicyDate();
    }

    /** Set the sheet's policy date, none for the sheet's today; it moves how live figures round, and the figures
     * it moves are written after. */
    @Transactional
    public LocalDate setPolicyDate(String user, String sheetId, LocalDate policyDate) {
        sheets.lock(sheetId);
        Sheet sheet = find(sheetId);
        Snapshot before = rollup.snapshot(sheetId);
        sheet.setPolicyDate(policyDate);
        sheetRepository.flush();
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=policy-date value="
                + (policyDate != null ? policyDate.toString() : ""));
        rollup.recordChanges(user, sheetId, before);
        return policyDate;
    }

    /** The sheet's period numbering date: while the sheet's today is on or after it, a claim opened is numbered
     * within its period; none means off. */
    @Transactional(readOnly = true)
    public LocalDate periodNumberingFrom(String sheetId) {
        return find(sheetId).getPeriodNumberingFrom();
    }

    /** Set the sheet's period numbering date, none to turn it off; it numbers only claims opened from now on. */
    @Transactional
    public LocalDate setPeriodNumberingFrom(String user, String sheetId, LocalDate from) {
        sheets.lock(sheetId);
        Sheet sheet = find(sheetId);
        sheet.setPeriodNumberingFrom(from);
        sheetRepository.flush();
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=period-numbering-from value="
                + (from != null ? from.toString() : ""));
        return from;
    }

    /** Set the sheet's cap from a date (the sheet's today when none), none to remove it from then; it moves
     * every due-total above the cap in force on the sheet's today, and the figures it moves are written after. */
    @Transactional
    public BigDecimal setCap(String user, String sheetId, BigDecimal cap, LocalDate from) {
        BigDecimal value = cap != null ? cap.setScale(2) : null;
        record(user, sheetId, Sheet.CAP, from, value, value != null ? value.toPlainString() : "", true);
        return value;
    }

    /** Set the sheet's proof threshold from a date (the sheet's today when none), none to remove it from then; it
     * moves no figure, only whether a claim dated from then needs a proof to be settled or approved. */
    @Transactional
    public BigDecimal setProofThreshold(String user, String sheetId, BigDecimal threshold, LocalDate from) {
        BigDecimal value = threshold != null ? threshold.setScale(2) : null;
        record(user, sheetId, Sheet.PROOF_THRESHOLD, from, value, value != null ? value.toPlainString() : "",
                false);
        return value;
    }

    /** Set the sheet's grace days, none to turn them off; not dated, and they close no period until the sheet's
     * today is next changed. */
    @Transactional
    public Integer setGraceDays(String user, String sheetId, Integer days) {
        sheets.lock(sheetId);
        Sheet sheet = find(sheetId);
        sheet.setGraceDays(days);
        sheetRepository.flush();
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=grace-days value="
                + (days != null ? days.toString() : ""));
        return days;
    }

    /** Give an action the roles that may take it, none (empty) to keep the standing rule; not dated, and it moves
     * no figure. */
    @Transactional
    public List<Role> setPermission(String user, String sheetId, Permission action, List<Role> given) {
        sheets.lock(sheetId);
        Sheet sheet = find(sheetId);
        String shown = String.join(",", given.stream().map(Role::code).toList());
        sheet.setPermission(action.code(), shown);
        sheetRepository.flush();
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=" + action.key() + " value="
                + shown);
        return given;
    }

    /** The roles the sheet gives an action, comma separated; blank when it keeps the standing rule. */
    public static String permissionOf(Sheet sheet, Permission action) {
        String roles = sheet.getPermission(action.code());
        return roles != null ? roles : "";
    }

    /** Refuse an action the user's role is not allowed by the sheet's permission matrix, or by the standing rule
     * when the sheet gives the action no roles of its own. */
    @Transactional(readOnly = true)
    public void requirePermitted(String sheetId, String user, Permission action) {
        String given = find(sheetId).getPermission(action.code());
        List<Role> allowed = given == null ? action.standing()
                : Arrays.stream(given.split(",")).map(Role::of).flatMap(Optional::stream).toList();
        if (!allowed.contains(roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role cannot " + action.doing() + ".");
        }
    }

    /** Refuse settling or approving a claim dated on a date, with this due and proofs count, when its due is
     * above the proof threshold in force on its date and it has no proof; a due of n/a is above no threshold. */
    @Transactional(readOnly = true)
    public void requireProof(String sheetId, LocalDate date, BigDecimal due, int proofs) {
        BigDecimal threshold = find(sheetId).proofThresholdOn(date);
        if (threshold != null && due != null && due.compareTo(threshold) > 0 && proofs == 0) {
            throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,
                    "A claim with a due above " + threshold.setScale(2).toPlainString() + " needs a proof first.");
        }
    }

    /** Record a dated setting's value from a date, the sheet's today when none is given, replacing one recorded
     * from that date; the audit line carries the from-date only when one was given. When {@code movesFigures},
     * the figures it moves are written after. */
    private void record(String user, String sheetId, String key, LocalDate from, BigDecimal value, String shown,
            boolean movesFigures) {
        sheets.lock(sheetId);
        Sheet sheet = find(sheetId);
        Snapshot before = movesFigures ? rollup.snapshot(sheetId) : null;
        sheet.record(key, from != null ? from : sheet.getToday(), value);
        sheetRepository.flush();
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=" + key + " value=" + shown
                + (from != null ? " from=" + from : ""));
        if (movesFigures) {
            rollup.recordChanges(user, sheetId, before);
        }
    }

    /** Whether a user may settle a claim of this due outright: a due of n/a is within any limit, and a steward
     * settles anything; a clerk's settle above the clerk limit goes to a steward instead. */
    @Transactional(readOnly = true)
    public boolean maySettle(String sheetId, String user, BigDecimal due) {
        BigDecimal limit = clerkLimit(sheetId);
        return limit == null || due == null || due.compareTo(limit) <= 0 || roleOf(sheetId, user) == Role.STEWARD;
    }

    /** Refuse a change only a steward may make, such as approving or rejecting a PENDING claim. */
    @Transactional(readOnly = true)
    public void requireSteward(String sheetId, String user) {
        if (roleOf(sheetId, user) != Role.STEWARD) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "Only a steward can do that.");
        }
    }

    private Sheet find(String sheetId) {
        return sheetRepository.findById(sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
    }
}
