// The home page: the active sheet's settings and people, once a sheet is loaded.
@Component({
  selector: 'app-home',
  imports: [People, Settings],
  template: `
    @if (session.sheetId()) {
      <app-settings />
      <app-people />
    } @else {
      <p data-testid="home-empty">Nothing here yet.</p>
    }
  `,
